import {useEffect,useMemo,useState} from 'react';
import {Activity,AlertOctagon,AlertTriangle,ArrowDownRight,ArrowRight,ArrowUpRight,BarChart3,Bell,BookOpen,Check,CheckCircle2,ChevronDown,ChevronLeft,ChevronRight,ClipboardList,Clock3,Compass,Copy,Database,Download,ExternalLink,Eye,FileCheck2,FileSearch,FileText,Filter,Gauge,Globe2,HardDrive,HelpCircle,Layers,MapPin,Menu,MoreHorizontal,Pause,Play,Plus,Radio,RefreshCw,Search,Settings,ShieldAlert,ShieldCheck,SlidersHorizontal,Square,Upload,User,Users,Wifi,X} from 'lucide-react';
import {Area,AreaChart,CartesianGrid,Line,LineChart,ResponsiveContainer,Tooltip as ChartTooltip,XAxis,YAxis} from 'recharts';
import {auditSeed,initialAlerts,reports,telemetry,wells} from './data/mockData';
