import {auditService} from './services/mockServices';

type Page='Overview'|'Offset wells'|'Well details'|'Knowledge search'|'Evidence viewer'|'Live monitoring'|'Alerts'|'Documents'|'Review queue'|'Analytics'|'Audit log';
const nav:{name:Page;icon:any;group:string}[]=[{name:'Overview',icon:Activity,group:'Workspace'},{name:'Offset wells',icon:MapPin,group:'Workspace'},{name:'Knowledge search',icon:FileSearch,group:'Workspace'},{name:'Live monitoring',icon:Radio,group:'Operations'},{name:'Alerts',icon:AlertTriangle,group:'Operations'},{name:'Documents',icon:FileText,group:'Knowledge'},{name:'Review queue',icon:ClipboardList,group:'Knowledge'},{name:'Analytics',icon:BarChart3,group:'Insights'},{name:'Audit log',icon:ShieldCheck,group:'Insights'}];
const fmt=(n:number)=>n.toLocaleString('en-US');
export default function App(){
 const [logged,setLogged]=useState(false),[role,setRole]=useState('Drilling Engineer'),[page,setPage]=useState<Page>('Overview'),[mobileNav,setMobileNav]=useState(false),[active,setActive]=useState(wells[0]),[selected,setSelected]=useState<Well|null>(null),[alerts,setAlerts]=useState<Alert[]>(initialAlerts),[search,setSearch]=useState(''),[query,setQuery]=useState(''),[filter,setFilter]=useState('All events'),[playing,setPlaying]=useState(false),[depth,setDepth]=useState(2015),[speed,setSpeed]=useState(1),[toast,setToast]=useState(''),[evidence,setEvidence]=useState<{well:Well;event:Well['events'][number]}|null>(null),[reviews,setReviews]=useState(['RPT-021']),[docs,setDocs]=useState(24),[uploading,setUploading]=useState(false),[radius,setRadius]=useState(15),[roleMenu,setRoleMenu]=useState(false),[glossary,setGlossary]=useState(false),[filtersOpen,setFiltersOpen]=useState(false),[ackNote,setAckNote]=useState('');
 const [audit,setAudit]=useState(auditSeed);
 const notify=(m:string)=>{setToast(m);window.setTimeout(()=>setToast(''),2800)};
 const log=(action:string,entity:string)=>{auditService.record(action);setAudit(a=>[{user:'A. Sharma',role,action,entity,time:new Date().toLocaleTimeString('en-GB'),status:'Complete'},...a]);};
 const go=(p:Page)=>{setPage(p);setMobileNav(false);setSelected(null)};
 useEffect(()=>{if(!playing)return;const timer=window.setInterval(()=>setDepth(d=>{const next=d+5*speed;if(d<2000&&next>=2000&&!alerts.some(a=>a.status==='New')){setAlerts(as=>[{id:`ALT-${String(as.length+1).padStart(3,'0')}`,wellId:active.id,type:'Lost circulation',severity:'High',current:next,from:2000,to:2080,sources:['RPT-003','RPT-006'],status:'New',created:new Date().toLocaleTimeString('en-GB')},...as]);log('Alert generated','Historical interval · Lost circulation');notify('Historical interval alert generated · evidence attached');}return next>2425?1780:next}),1000);return()=>window.clearInterval(timer)},[playing,speed,alerts,active]);
 const results=useMemo(()=>{const q=query.toLowerCase();return reports.filter(r=>{const w=wells.find(x=>x.id===r.wellId)!;const ev=w.events[0];const match=!q||`${r.filename} ${r.snippet} ${w.name} ${ev.type}`.toLowerCase().includes(q)||(/lost|circulation/.test(q)&&/lost|circulation/.test(r.snippet.toLowerCase()))||(/stuck/.test(q)&&/stuck/.test(r.snippet.toLowerCase()));return match&&(filter==='All events'||ev.type===filter)})},[query,filter]);
 const rank=useMemo(()=>wells.filter(w=>w.id!==active.id).map(w=>{const dist=Math.sqrt(Math.pow((w.lat-active.lat)*111,2)+Math.pow((w.lon-active.lon)*94,2));const geo=Math.max(35,Math.round(100-dist*3));const form=w.formation===active.formation?100:42;const overlap=w.events[0].to<=active.currentDepth+450&&w.events[0].from>=active.currentDepth-450?84:58;const recent=76-(Number(w.id.slice(-2))%5)*5;return{well:w,dist:dist.toFixed(1),geo,form,overlap,recent,score:Math.round(geo*.28+form*.35+overlap*.25+recent*.12)}}).sort((a,b)=>b.score-a.score),[active]);
 const openEvent=(w:Well)=>{setEvidence({well:w,event:w.events[0]});setPage('Evidence viewer')};
 const acknowledge=(a:Alert,status:'Acknowledged'|'Dismissed'|'Under investigation')=>{setAlerts(as=>as.map(x=>x.id===a.id?{...x,status}:x));log(`Alert ${status.toLowerCase()}`,a.id+' · '+a.type);notify(`Alert ${status.toLowerCase()}`)};
 const currentAlert=alerts.find(a=>a.status==='New')||alerts[0];
 if(!logged)return <Login onLogin={(r)=>{setRole(r);setLogged(true)}} role={role} setRole={setRole}/>;
 return <div className="app-shell"><aside className={`sidebar ${mobileNav?'mobile-open':''}`}><div className="brand"><div className="brand-symbol"><Activity size={19}/></div><div><b>eRTMAC<span>·</span>NWIS</b><small>OFFSET WELL INTELLIGENCE</small></div><button className="icon-btn close-nav" onClick={()=>setMobileNav(false)} aria-label="Close navigation"><X size={17}/></button></div><div className="field-pill"><span className="field-dot"/><span><b>Upper Assam Basin</b><small>DEMO FIELD · SYNTHETIC</small></span><ChevronDown size={14}/></div><div className="nav-scroll">{['Workspace','Operations','Knowledge','Insights'].map(group=><div className="nav-group" key={group}><div className="nav-label">{group}</div>{nav.filter(n=>n.group===group).map(n=><button key={n.name} className={`nav-item ${page===n.name?'active':''}`} onClick={()=>go(n.name)}><n.icon size={17}/><span>{n.name}</span>{n.name==='Alerts'&&alerts.some(a=>a.status==='New')&&<i className="nav-count">{alerts.filter(a=>a.status==='New').length}</i>}</button>)}</div>)}</div><div className="sidebar-foot"><div className="health"><span className="health-dot"/><span><b>All systems operational</b><small>Last sync · 14 sec ago</small></span><MoreHorizontal size={16}/></div><div className="profile" onClick={()=>setRoleMenu(v=>!v)}><div className="avatar">AS</div><div><b>A. Sharma</b><small>{role}</small></div><ChevronDown size={14}/></div>{roleMenu&&<div className="role-pop">{['Drilling Engineer','Geologist','Manager','Administrator'].map(r=><button key={r} onClick={()=>{setRole(r);setRoleMenu(false);notify(`Viewing as ${r}`)}}>{r}{role===r&&<Check size={14}/>}</button>)}</div>}</div></aside>{mobileNav&&<div className="mobile-shade" onClick={()=>setMobileNav(false)}/>}
 <main className="main-area"><header className="topbar"><button className="icon-btn menu-btn" onClick={()=>setMobileNav(true)} aria-label="Open navigation"><Menu size={19}/></button><div className="crumb"><span>Operations</span><ChevronRight size={14}/><b>{page}</b></div><div className="top-actions"><div className="top-live"><span className="pulse"/> DEMO SYSTEM <span className="top-divider"/> <Wifi size={14}/> FEED CONNECTED</div><button className="icon-btn help-btn" onClick={()=>setGlossary(true)} aria-label="Open glossary"><HelpCircle size={18}/></button><button className="icon-btn notif-btn" onClick={()=>go('Alerts')} aria-label="Notifications"><Bell size={18}/>{alerts.some(a=>a.status==='New')&&<i/>}</button><div className="top-user"><div className="avatar sm">AS</div><ChevronDown size={13}/></div></div></header><div className="content-wrap"><div className="prototype-banner"><span><span className="banner-pip"/> SYNTHETIC DEMONSTRATION DATA</span><span>Prototype environment <b>·</b> No live OIL systems connected</span></div>{page==='Overview'&&<Overview go={go} rank={rank} alerts={alerts} onAlert={()=>go('Alerts')} onWell={(w)=>{setSelected(w);go('Well details')}} depth={depth} docs={docs}/>}{page==='Offset wells'&&<OffsetWells active={active} setActive={setActive} rank={rank} onWell={w=>{setSelected(w);go('Well details')}} radius={radius} setRadius={setRadius} filter={filter} setFilter={setFilter} notify={notify}/>}{page==='Well details'&&<WellDetails well={selected||rank[0].well} rank={rank} onEvidence={openEvent} go={go}/>}{page==='Knowledge search'&&<KnowledgeSearch query={query} setQuery={setQuery} results={results} filter={filter} setFilter={setFilter} onSearch={()=>{log('Search performed',query||'All indexed reports');}} onEvidence={openEvent} onFilters={()=>setFiltersOpen(!filtersOpen)} filtersOpen={filtersOpen}/>}{page==='Evidence viewer'&&<EvidenceViewer evidence={evidence||{well:wells[2],event:wells[2].events[0]}} go={go} notify={notify}/>}{page==='Live monitoring'&&<Monitoring active={active} depth={depth} setDepth={setDepth} playing={playing} setPlaying={setPlaying} speed={speed} setSpeed={setSpeed} alerts={alerts} go={go} onEvidence={openEvent}/>}{page==='Alerts'&&<AlertsPage alerts={alerts} action={acknowledge} audit={audit} note={ackNote} setNote={setAckNote} onEvidence={()=>openEvent(wells[2])}/>}{page==='Documents'&&<Documents docs={docs} setDocs={setDocs} uploading={uploading} setUploading={setUploading} reviews={reviews} setPage={go} notify={notify}/>}{page==='Review queue'&&<ReviewQueue reviews={reviews} setReviews={setReviews} log={log} notify={notify} onEvidence={()=>openEvent(wells[10])}/>}{page==='Analytics'&&<Analytics/>}{page==='Audit log'&&<Audit audit={audit}/>}</div><footer className="footer"><span>eRTMAC-NWIS <b>·</b> Prototype v0.1.0</span><span>All well data shown is fictional and for demonstration purposes only.</span><button onClick={()=>setGlossary(true)}>Glossary <ArrowRight size={12}/></button></footer></main><div className="safety-fixed"><ShieldAlert size={14}/><span>This system provides historical decision support only. A qualified drilling engineer must validate all operational decisions.</span></div>{toast&&<div className="toast"><CheckCircle2 size={17}/>{toast}</div>}{glossary&&<Glossary onClose={()=>setGlossary(false)}/>}</div>
}

function Login({onLogin,role,setRole}:{onLogin:(r:string)=>void;role:string;setRole:(r:string)=>void}){const [name,setName]=useState('A. Sharma');const [password,setPassword]=useState('demo2026');return <div className="login-page"><div className="login-grid"/><div className="login-orbit orbit-one"/><div className="login-orbit orbit-two"/><div className="login-top"><div className="brand-symbol"><Activity size={19}/></div><span>OIL INDIA LIMITED <i>·</i> INNOVATION DEMONSTRATION</span><span className="login-sec"><ShieldCheck size={14}/> SECURE DEMO ENVIRONMENT</span></div><div className="login-content"><div className="login-left"><div className="eyebrow"><span className="health-dot"/> DRILLING OPERATIONS INTELLIGENCE</div><h1>Experience the<br/><em>context behind</em><br/>every well.</h1><p>Historical knowledge, connected to the well in front of you. Explore an evidence-grounded prototype for offset-well intelligence.</p><div className="login-proof"><span><MapPin size={15}/> 12 synthetic wells</span><span><FileCheck2 size={15}/> 24 indexed reports</span><span><Radio size={15}/> Replayable telemetry</span></div><div className="login-wave"><svg viewBox="0 0 660 112" preserveAspectRatio="none"><path d="M0,79 C45,76 44,45 88,47 S135,88 174,69 S223,20 264,42 S309,92 352,67 S408,32 443,50 S499,94 535,58 S600,50 660,40" fill="none" stroke="#00b8d9" strokeWidth="2"/><path d="M0,94 C50,92 76,83 118,85 S180,57 221,67 S267,85 312,88 S382,60 424,76 S497,99 536,85 S612,68 660,72" fill="none" stroke="#13b8a6" strokeWidth="1" opacity=".48"/></svg><div className="wave-label"><span>LIVE FEED SIMULATION</span><span>27° 27' 18.2" N &nbsp; 95° 20' 41.7" E</span></div></div></div><div className="login-card"><div className="login-card-top"><div className="login-logo"><div className="brand-symbol"><Activity size={18}/></div><div><b>eRTMAC<span>·</span>NWIS</b><small>NEARBY WELLS INTELLIGENCE SYSTEM</small></div></div><div className="synthetic-tag"><span/> SYNTHETIC DATA</div></div><h2>Welcome to the demo</h2><p className="login-sub">Sign in to explore the prototype environment.</p><label className="field-label">USERNAME</label><div className="input-wrap"><User size={16}/><input value={name} onChange={e=>setName(e.target.value)} aria-label="Username"/></div><label className="field-label">PASSWORD</label><div className="input-wrap"><ShieldCheck size={16}/><input type="password" value={password} onChange={e=>setPassword(e.target.value)} aria-label="Password"/></div><label className="field-label">DEMO ROLE</label><div className="role-select"><select value={role} onChange={e=>setRole(e.target.value)}><option>Drilling Engineer</option><option>Geologist</option><option>Manager</option><option>Administrator</option><option>eRTMAC Analyst</option></select><ChevronDown size={15}/></div><button className="primary-btn login-button" onClick={()=>onLogin(role)}>Enter demonstration <ArrowRight size={16}/></button><div className="login-note"><ShieldCheck size={15}/><span><b>For demonstration only.</b> No live systems, wells, or operational data are connected.</span></div><div className="login-bottom"><span>OIL INDIA LIMITED</span><span>SIH 2026 · SIH26121</span></div></div></div><div className="login-footer">eRTMAC-NWIS <b>·</b> SOFTWARE PROTOTYPE <span>Historical decision support · Human judgment required</span></div></div>}

function PageHeading({eyebrow,title,sub,actions}:{eyebrow:string;title:string;sub:string;actions?:any}){return <div className="page-heading"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{sub}</p></div>{actions&&<div className="heading-actions">{actions}</div>}</div>}
function Button({children,onClick,kind='secondary',icon:Icon}:{children:any;onClick?:()=>void;kind?:'primary'|'secondary'|'quiet'|'danger';icon?:any}){return <button className={`${kind}-btn`} onClick={onClick}>{Icon&&<Icon size={15}/>} {children}</button>}
function Metric({label,value,unit,icon:Icon,trend,accent='blue'}:{label:string;value:string;unit?:string;icon:any;trend?:string;accent?:string}){return <div className="metric-card"><div className={`metric-icon ${accent}`}><Icon size={18}/></div><div className="metric-copy"><div className="metric-label">{label}</div><div className="metric-value">{value}<span>{unit}</span></div>{trend&&<div className="metric-trend">{trend}</div>}</div><div className="metric-spark"><svg viewBox="0 0 64 28"><path d="M0 22 L10 18 L18 21 L28 9 L36 14 L46 5 L54 10 L64 2" fill="none" stroke="currentColor" strokeWidth="1.7"/></svg></div></div>}
function WellMap({rank,onWell,compact=false}:{rank:{well:Well;score:number;dist:string}[];onWell:(w:Well)=>void;compact?:boolean}){const all=[wells[0],...rank.slice(0,compact?7:11).map(x=>x.well)];return <div className={`map-canvas ${compact?'map-compact':''}`}><div className="map-controls"><button aria-label="Zoom in">+</button><button aria-label="Zoom out">−</button><button aria-label="Map layers"><Layers size={15}/></button></div><div className="map-scale">0 ─────── 2 km</div><div className="map-road road-a"/><div className="map-road road-b"/><div className="map-river river-a"/><div className="map-zone zone-a">SYNTHETIC SANDSTONE A</div><div className="map-zone zone-b">DELTAIC SEQUENCE D</div><div className="map-label label-a">NORTH FIELD</div><div className="map-label label-b">EAST BLOCK</div>{all.map((w,i)=>{const left=15+((w.lon-95.25)*360),top=20+((27.53-w.lat)*440);return <button key={w.id} className={`well-marker ${i===0?'marker-active':''} ${w.events[0].type==='Lost circulation'&&i>0?'marker-risk':''}`} style={{left:`${Math.min(90,Math.max(7,left))}%`,top:`${Math.min(85,Math.max(12,top))}%`}} onClick={()=>onWell(w)} title={`${w.name} · ${w.events[0].type}`}><span/><b>{i===0?'A':w.id.slice(-3)}</b></button>})}<div className="map-watermark"><Globe2 size={13}/> SYNTHETIC FIELD MAP</div><div className="map-legend"><span><i className="legend-active"/> Active well</span><span><i className="legend-historical"/> Offset well</span><span><i className="legend-risk"/> Historical event</span></div></div>}

function Overview({go,rank,alerts,onAlert,onWell,depth,docs}:{go:(p:Page)=>void;rank:any[];alerts:Alert[];onAlert:()=>void;onWell:(w:Well)=>void;depth:number;docs:number}){const a=alerts.find(x=>x.status==='New');return <><PageHeading eyebrow="OPERATIONS OVERVIEW · 26 SEP 2026" title="Good morning, A. Sharma" sub="Active well intelligence across the Upper Assam Basin." actions={<><Button icon={BookOpen} onClick={()=>go('Knowledge search')}>Search reports</Button><Button kind="primary" icon={Compass} onClick={()=>go('Offset wells')}>Find offset wells</Button></>}/><div className="callout"><ShieldCheck size={16}/><span><b>Decision support only.</b> Historical evidence is surfaced for qualified engineers to review. No autonomous recommendations.</span><button onClick={()=>go('Knowledge search')}>How evidence works <ArrowRight size={13}/></button></div><section className="metric-grid"><Metric label="ACTIVE WELL · OIL-SYN-001" value={fmt(depth)} unit=" m" icon={Gauge} trend="↑ 15 m in last 15 min" accent="cyan"/><Metric label="CURRENT FORMATION" value="Sandstone" unit=" A" icon={Layers} trend="Synthetic formation interval" accent="teal"/><Metric label="OPEN ALERTS" value={String(alerts.filter(x=>x.status==='New').length).padStart(2,'0')} icon={AlertTriangle} trend={a?'Risk interval · 2 cited offsets':'No unacknowledged alerts'} accent="amber"/><Metric label="INDEXED REPORTS" value={String(docs).padStart(2,'0')} icon={FileText} trend={`${reports.filter(r=>r.status==='Needs review').length} pending human review`} accent="purple"/><Metric label="SIMILAR WELLS" value={String(rank.filter(r=>r.score>=65).length).padStart(2,'0')} icon={MapPin} trend="Within 15 km · ranked by 4 factors" accent="blue"/></section><div className="overview-grid"><section className="panel map-panel"><div className="panel-heading"><div><div className="panel-title">Well locations &amp; offset context <span className="live-badge"><i/> UPDATED</span></div><div className="panel-sub">Synthetic field view · Upper Assam Basin</div></div><button className="text-link" onClick={()=>go('Offset wells')}>Explore map <ArrowRight size={14}/></button></div><WellMap rank={rank} onWell={onWell} compact/></section><section className="panel alert-panel"><div className="panel-heading"><div><div className="panel-title">Priority alerts <span className="count-pill">{alerts.filter(x=>x.status==='New').length} new</span></div><div className="panel-sub">Historical intervals near active depth</div></div><button className="icon-btn" aria-label="More alerts" onClick={onAlert}><MoreHorizontal size={18}/></button></div>{a?<div className="priority-alert"><div className="alert-icon"><AlertTriangle size={17}/></div><div className="priority-content"><div className="alert-meta"><span className="severity-pill high">HIGH</span><span>09:42 · {a.wellId}</span></div><h3>Lost circulation interval ahead</h3><p>Active depth is within <b>{fmt(Math.max(0,a.to-depth))} m</b> of a historical risk interval identified in 2 comparable offsets.</p><div className="alert-range"><div className="range-track"><i style={{left:`${Math.max(6,Math.min(84,(depth-a.from)/(a.to-a.from)*100))}%`}}/><b/></div><div><span>Current · {fmt(depth)} m</span><span>Interval · {fmt(a.from)}–{fmt(a.to)} m</span></div></div><div className="alert-foot"><span><FileText size={13}/> RPT-003 p.4 · RPT-006 p.6</span><button onClick={onAlert}>Review alert <ArrowRight size={13}/></button></div></div></div>:<Empty icon={CheckCircle2} title="No new alerts" sub="New evidence-backed risk intervals appear here."/>}<div className="alert-bottom"><span><Radio size={14}/> Alert engine</span><b><i className="health-dot"/> Monitoring active well</b></div></section></div><div className="lower-grid"><section className="panel"><div className="panel-heading"><div><div className="panel-title">Most relevant offset wells</div><div className="panel-sub">Formation match and proximity weighted together</div></div><button className="text-link" onClick={()=>go('Offset wells')}>View all <ArrowRight size={14}/></button></div><div className="offset-mini-list">{rank.slice(0,4).map((r:any,i:number)=><button className="offset-mini" key={r.well.id} onClick={()=>go('Offset wells')}><span className="rank-num">0{i+1}</span><span className="well-mini-icon"><MapPin size={15}/></span><span className="well-name-mini"><b>{r.well.name}</b><small>{r.dist} km · {r.well.formation}</small></span><span className="mini-event"><i className={r.well.events[0].type==='Lost circulation'?'amber-dot':'blue-dot'}/>{r.well.events[0].type}</span><span className="score-mini">{r.score}<small> SCORE</small></span><ChevronRight size={15}/></button>)}</div></section><section className="panel activity-panel"><div className="panel-heading"><div><div className="panel-title">Recent well events</div><div className="panel-sub">Latest events in indexed reports</div></div><button className="text-link" onClick={()=>go('Knowledge search')}>Search <ArrowRight size={14}/></button></div><div className="recent-events">{[wells[2],wells[1],wells[5]].map((w,i)=><div className="recent-event" key={w.id}><div className={`event-dot event-${i}`}/><div className="recent-event-copy"><b>{w.events[0].type}</b><small>{w.name} · {fmt(w.events[0].from)}–{fmt(w.events[0].to)} m</small></div><button className="citation-mini" onClick={()=>{}}>p.{w.events[0].page} <ExternalLink size={11}/></button><span className="event-date">{i===0?'Aug 14':'Aug 12'}</span></div>)}</div></section></div><div className="status-strip"><div><div className="status-icon green"><Radio size={16}/></div><span><b>Telemetry feed</b><small>Connected · replay mode</small></span><i/></div><div><div className="status-icon blue"><Database size={16}/></div><span><b>Document index</b><small>{docs} synthetic reports</small></span><i/></div><div><div className="status-icon purple"><Search size={16}/></div><span><b>Hybrid search</b><small>Keyword + semantic</small></span><i/></div><div><div className="status-icon amber"><ShieldCheck size={16}/></div><span><b>Audit trail</b><small>Recording activity</small></span><i/></div></div></>}

function OffsetWells({active,setActive,rank,onWell,radius,setRadius,filter,setFilter,notify}:{active:Well;setActive:(w:Well)=>void;rank:any[];onWell:(w:Well)=>void;radius:number;setRadius:(v:number)=>void;filter:string;setFilter:(v:string)=>void;notify:(s:string)=>void}){const [term,setTerm]=useState('');const filtered=rank.filter(r=>(!term||r.well.name.toLowerCase().includes(term.toLowerCase()))&&Number(r.dist)<=radius&&(filter==='All events'||r.well.events[0].type===filter));const [explain,setExplain]=useState(false);return <><PageHeading eyebrow="WELL INTELLIGENCE · DISCOVERY" title="Offset well discovery" sub="Find wells with relevant geological and operational context." actions={<Button icon={Download} onClick={()=>notify('Offset list exported as synthetic CSV')}>Export list</Button>}/><div className="callout compact-callout"><ShieldCheck size={16}/><span>Similarity is a transparent screening aid. Review the factor breakdown and source reports before drawing conclusions.</span></div><div className="discovery-toolbar"><div className="active-well-select"><label>ACTIVE WELL</label><select value={active.id} onChange={e=>setActive(wells.find(w=>w.id===e.target.value)!)}>{wells.map(w=><option key={w.id} value={w.id}>{w.name}</option>)}</select><ChevronDown size={15}/></div><div className="search-control"><Search size={16}/><input placeholder="Search well name…" value={term} onChange={e=>setTerm(e.target.value)}/></div><label className="range-control"><span>RADIUS <b>{radius} km</b></span><input type="range" min="1" max="25" value={radius} onChange={e=>setRadius(+e.target.value)}/></label><select className="filter-select" value={filter} onChange={e=>setFilter(e.target.value)}><option>All events</option>{['Lost circulation','Stuck pipe','Kick','NPT','Equipment failure'].map(v=><option key={v}>{v}</option>)}</select><button className="icon-btn" onClick={()=>setExplain(!explain)} aria-label="Explain similarity score"><HelpCircle size={17}/></button></div>{explain&&<div className="score-explain"><b>Similarity is calculated using:</b> geographic distance (28%), formation match (35%), depth overlap (25%), and report recency (12%). Scores support discovery and do not indicate a forecast.</div>}<div className="discovery-layout"><section className="panel discovery-map"><div className="panel-heading"><div><div className="panel-title">Synthetic field map</div><div className="panel-sub">Click a marker to inspect a well</div></div><div className="map-layer-chips"><span><i className="legend-active"/> Active well</span><span><i className="legend-risk"/> Event well</span></div></div><WellMap rank={filtered} onWell={onWell}/></section><section className="panel ranked-panel"><div className="panel-heading"><div><div className="panel-title">Ranked offsets</div><div className="panel-sub">{filtered.length} wells within {radius} km</div></div><button className="text-link" onClick={()=>setExplain(!explain)}>Score guide</button></div><div className="rank-scroll">{filtered.map((r,i)=><div className="rank-card" key={r.well.id}><div className="rank-card-top"><span className="rank-num">{String(i+1).padStart(2,'0')}</span><div className="rank-well"><b>{r.well.name}</b><small><MapPin size={11}/> {r.dist} km &nbsp;·&nbsp; {r.well.formation}</small></div><div className="rank-score">{r.score}<small>SIMILARITY</small></div></div><div className="score-bar"><i style={{width:`${r.score}%`}}/></div><div className="score-factors"><span>Geo. <b>{r.geo}</b></span><span>Formation <b>{r.form}</b></span><span>Depth <b>{r.overlap}</b></span><span>Recency <b>{r.recent}</b></span></div><div className="rank-foot"><span><i className="amber-dot"/> {r.well.events.length} event · {r.well.events[0].type}</span><Button onClick={()=>onWell(r.well)}>View well <ArrowRight size={12}/></Button></div></div>)}{filtered.length===0&&<Empty icon={MapPin} title="No comparable wells found" sub="Try a wider radius or remove filters."/>}</div></section></div></>}

function WellDetails({well,rank,onEvidence,go}:{well:Well;rank:any[];onEvidence:(w:Well)=>void;go:(p:Page)=>void}){return <><PageHeading eyebrow="WELL RECORD · SYNTHETIC" title={well.name} sub="Wellbore history, formations and source-linked events." actions={<><Button icon={ArrowLeftIcon} onClick={()=>go('Offset wells')}>Back to discovery</Button><Button kind="primary" icon={FileSearch} onClick={()=>go('Knowledge search')}>Search this well</Button></>}/><div className="well-hero"><div className="well-hero-main"><span className="status-pill active">● {well.status.toUpperCase()}</span><h2>{well.name}</h2><p>{well.formation} <span>·</span> {well.phase} <span>·</span> Spud {well.spud}</p></div><div className="well-hero-metric"><small>TOTAL DEPTH</small><b>{fmt(well.totalDepth)} <i>m</i></b></div><div className="well-hero-metric"><small>COORDINATES</small><b>{well.lat.toFixed(4)}° N</b><small>{well.lon.toFixed(4)}° E</small></div><div className="well-hero-metric"><small>OFFSET SCORE</small><b>{well.status==='Active'?'—':(rank.find(r=>r.well.id===well.id)?.score||78)}<i> /100</i></b></div></div><div className="details-two"><section className="panel"><div className="panel-heading"><div><div className="panel-title">Formation intervals</div><div className="panel-sub">Depth measured in metres</div></div><span className="synthetic-tag"><span/> SYNTHETIC</span></div><div className="formation-track">{['Shale B','Sandstone A','Deltaic D','Limestone C'].map((f,i)=><div className="formation-row" key={f}><span>{fmt(i*900)} m</span><div className="formation-name">{f}<div className={`formation-bar f${i}`}/></div><span>{fmt((i+1)*900)} m</span></div>)}</div></section><section className="panel"><div className="panel-heading"><div><div className="panel-title">Well parameters</div><div className="panel-sub">Synthetic operational summary</div></div></div><div className="chart-wrap params-chart"><ResponsiveContainer width="100%" height="100%"><LineChart data={telemetry}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="time" tick={{fontSize:10}}/><YAxis tick={{fontSize:10}}/><ChartTooltip/><Line dataKey="rop" stroke="#00a4c7" dot={false} strokeWidth={2}/><Line dataKey="torque" stroke="#5b6ee1" dot={false} strokeWidth={2}/></LineChart></ResponsiveContainer></div><div className="chart-legend"><span><i className="dot-cyan"/> Rate of penetration</span><span><i className="dot-purple"/> Torque</span></div></section></div><div className="details-two"><section className="panel"><div className="panel-heading"><div><div className="panel-title">Historical event timeline</div><div className="panel-sub">Indexed evidence · {well.events.length} event</div></div><button className="text-link" onClick={()=>go('Knowledge search')}>Search events <ArrowRight size={13}/></button></div><div className="timeline-list">{well.events.map(e=><div className="timeline-entry" key={e.id}><div className="timeline-stem"><i/></div><div className="timeline-body"><div className="timeline-meta"><span className="severity-pill high">{e.severity.toUpperCase()}</span><span>{e.date}</span></div><h3>{e.type} · {fmt(e.from)}–{fmt(e.to)} m</h3><p>{e.summary}</p><button className="citation-link" onClick={()=>onEvidence(well)}><FileText size={13}/>{e.report}.pdf · page {e.page}<ArrowRight size={12}/></button></div></div>)}</div></section><section className="panel"><div className="panel-heading"><div><div className="panel-title">Evidence record</div><div className="panel-sub">Source citation and extraction quality</div></div></div><div className="evidence-summary"><div className="evidence-doc-icon"><FileText size={21}/></div><div><b>{well.events[0].report}-DDR.pdf</b><small>Daily drilling report · {well.events[0].date}</small></div><span className="confidence-pill"><CheckCircle2 size={12}/> {Math.round(well.events[0].confidence*100)}%</span></div><div className="source-quote">“{well.events[0].summary}”</div><div className="evidence-facts"><span>EVENT DEPTH<b>{fmt(well.events[0].from)}–{fmt(well.events[0].to)} m</b></span><span>FORMATION<b>{well.formation}</b></span><span>SOURCE PAGE<b>Page {well.events[0].page}</b></span></div><Button kind="primary" icon={Eye} onClick={()=>onEvidence(well)}>Open source evidence</Button></section></div></>}
function ArrowLeftIcon({size=15}:any){return <ChevronLeft size={size}/>}
function KnowledgeSearch({query,setQuery,results,filter,setFilter,onSearch,onEvidence,onFilters,filtersOpen}:{query:string;setQuery:(s:string)=>void;results:any[];filter:string;setFilter:(s:string)=>void;onSearch:()=>void;onEvidence:(w:Well)=>void;onFilters:()=>void;filtersOpen:boolean}){const [searched,setSearched]=useState(false);return <><PageHeading eyebrow="KNOWLEDGE RETRIEVAL · HYBRID SEARCH" title="Search historical knowledge" sub="Find relevant events across indexed synthetic drilling reports." actions={<span className="search-mode"><span/> KEYWORD + SEMANTIC SEARCH</span>}/><section className="search-hero panel"><div className="big-search"><Search size={20}/><input value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>e.key==='Enter'&&(setSearched(true),onSearch())} placeholder="Ask about an event, formation, or depth interval…"/><button onClick={()=>{setSearched(true);onSearch()}}>Search <ArrowRight size={15}/></button></div><div className="query-suggestions"><span>TRY:</span>{['lost circulation near 2000 metres','stuck pipe in comparable sandstone wells','historical kick events','NPT causes between 1800 and 2200 metres'].map(q=><button key={q} onClick={()=>{setQuery(q);setSearched(true);onSearch()}}>{q}</button>)}</div></section><div className="search-content-grid"><aside className="panel filter-panel"><div className="panel-heading"><div className="panel-title"><SlidersHorizontal size={15}/> Filters</div><button className="text-link" onClick={()=>setFilter('All events')}>Clear</button></div><div className="filter-group"><label>EVENT TYPE</label><select value={filter} onChange={e=>setFilter(e.target.value)}><option>All events</option>{['Lost circulation','Stuck pipe','Kick','NPT','Equipment failure'].map(x=><option key={x}>{x}</option>)}</select></div><div className="filter-group"><label>WELL</label><select><option>All wells</option>{wells.map(w=><option key={w.id}>{w.name}</option>)}</select></div><div className="filter-group"><label>FORMATION</label><select><option>All formations</option>{['Synthetic Sandstone A','Synthetic Shale B','Synthetic Limestone C','Synthetic Deltaic Sequence D'].map(x=><option key={x}>{x}</option>)}</select></div><div className="filter-group"><label>DEPTH RANGE <b>1,800 – 2,200 m</b></label><input type="range" min="0" max="4500" defaultValue="2200"/></div><div className="filter-group"><label>MIN. CONFIDENCE</label><select><option>Any confidence</option><option>80% and above</option><option>90% and above</option></select></div><div className="filter-hint"><ShieldCheck size={14}/> Results cite source documents and pages. Search does not infer operational actions.</div></aside><div className="search-results-column"><section className="answer-card"><div className="answer-label"><span><Activity size={14}/> EVIDENCE SUMMARY</span><span className="confidence-pill"><CheckCircle2 size={12}/> HIGH EVIDENCE</span></div><h3>{results.length?query&&/stuck/i.test(query)?'One comparable offset records a stuck-pipe event.':'Two comparable offsets record lost-circulation events near this depth.':'No sufficient evidence found'}</h3><p>{results.length?'In synthetic reports for OIL-SYN-003 and OIL-SYN-006, drilling-fluid losses were recorded between 2,000–2,090 m in Synthetic Sandstone A. The snippets below are historical records, not an operational prediction.':'No matching historical evidence was found in the indexed reports. Do not treat this as proof that no risk exists.'}</p>{results.length>0&&<div className="answer-citations"><span>SUPPORTING SOURCES</span>{results.slice(0,3).map((r:any)=><button key={r.id} onClick={()=>onEvidence(wells.find(w=>w.id===r.wellId)!)}><FileText size={12}/>{r.filename} · p.{wells.find(w=>w.id===r.wellId)?.events[0].page}</button>)}</div>}</section><div className="result-header"><b>{searched?'Search results':'Relevant indexed evidence'} <span>{results.length}</span></b><button className="filter-mobile" onClick={onFilters}><Filter size={14}/> Filters</button><span>Ranked by relevance <ChevronDown size={13}/></span></div>{filtersOpen&&<div className="mobile-filter"><select value={filter} onChange={e=>setFilter(e.target.value)}><option>All events</option>{['Lost circulation','Stuck pipe','Kick','NPT','Equipment failure'].map(x=><option key={x}>{x}</option>)}</select></div>}{results.slice(0,8).map((r:any)=>{const w=wells.find(x=>x.id===r.wellId)!;const e=w.events[0];return <article className="result-card" key={r.id}><div className="result-card-head"><span className="event-type-chip"><i/> {e.type}</span><span className="result-match">{Math.round(e.confidence*100)}% evidence quality</span></div><h3>{w.name} <span>·</span> {w.formation}</h3><p>{e.summary}</p><div className="result-meta"><span><Gauge size={13}/>{fmt(e.from)}–{fmt(e.to)} m</span><span><Clock3 size={13}/>{e.date}</span><span><FileText size={13}/>{r.filename}</span></div><div className="result-foot"><span className="relevance"><i style={{width:`${Math.min(98,74+r.id.charCodeAt(4)%23)}%`}}/> RELEVANCE</span><button onClick={()=>onEvidence(w)}>View cited page <ArrowRight size={13}/></button></div></article>})}{results.length===0&&<Empty icon={FileSearch} title="No matching historical evidence" sub="Try a broader phrase, a different event type, or remove filters. An empty result is not proof that no risk exists."/>}</div></div></>}

function EvidenceViewer({evidence,go,notify}:{evidence:{well:Well;event:Well['events'][number]};go:(p:Page)=>void;notify:(s:string)=>void}){const {well,event}=evidence;const [page,setPage]=useState(event.page);const [flagged,setFlagged]=useState(false);return <><PageHeading eyebrow="SOURCE TRACEABILITY · REPORT VIEWER" title="Evidence viewer" sub="Inspect the original passage and the structured event record." actions={<Button icon={ArrowLeftIcon} onClick={()=>go('Knowledge search')}>Back to search</Button>}/><div className="evidence-view-head"><div className="evidence-file"><div className="pdf-icon"><FileText size={19}/></div><div><b>{event.report}-DDR.pdf</b><small>Daily drilling report · {well.name} · {event.date}</small></div></div><div className="citation-prominent"><span>VERIFIED CITATION</span><b>{event.report}-DDR.pdf <i>·</i> PAGE {page}</b></div><Button icon={Copy} onClick={()=>{navigator.clipboard?.writeText(`${event.report}-DDR.pdf, page ${page}`);notify('Citation copied to clipboard')}}>Copy citation</Button></div><div className="evidence-layout"><section className="panel pdf-view"><div className="pdf-toolbar"><span><FileText size={14}/> {event.report}-DDR.pdf</span><div><button aria-label="Previous page" onClick={()=>setPage(Math.max(1,page-1))}><ChevronLeft size={15}/></button><span>Page <b>{page}</b> of 12</span><button aria-label="Next page" onClick={()=>setPage(Math.min(12,page+1))}><ChevronRight size={15}/></button></div><button aria-label="Download report" onClick={()=>notify('Synthetic sample report is not available for download')}><Download size={14}/></button></div><div className="paper"><div className="paper-brand">FIELD OPERATIONS <span>DAILY DRILLING REPORT</span></div><div className="paper-rule"/><div className="paper-title">DAILY DRILLING REPORT <small>CONFIDENTIAL · SYNTHETIC SAMPLE</small></div><div className="paper-grid"><span>WELL <b>{well.name}</b></span><span>REPORT DATE <b>{event.date}</b></span><span>FORMATION <b>{well.formation}</b></span><span>REPORT NO. <b>{event.report}</b></span></div><div className="paper-section">OPERATIONS SUMMARY <i/></div><p>Continued drilling from {fmt(event.from-60)} m to {fmt(event.to+10)} m. Formation top as expected in Synthetic Sandstone A. Drilling parameters remained within the recorded operating range.</p><div className="paper-section">EVENTS / OBSERVATIONS <i/></div><div className="highlight-passage"><span>SOURCE PASSAGE · PAGE {page}</span><p>At approximately <b>{fmt(event.from)}–{fmt(event.to)} metres</b>, {event.summary.toLowerCase()} Operations team recorded the event in the daily report for review.</p></div><div className="paper-section">REMARKS <i/></div><p>Data shown in this report is fictional and included only to demonstrate document extraction and source citation behavior. This mock report is not an operational record.</p><div className="paper-sign">Prepared by: Synthetic Demo System <span>Page {page}</span></div></div><div className="pdf-pages"><button onClick={()=>setPage(Math.max(1,page-1))}><ChevronLeft size={13}/> Previous</button><span>Source passage highlighted for traceability</span><button onClick={()=>setPage(Math.min(12,page+1))}>Next <ChevronRight size={13}/></button></div></section><aside className="panel extraction-panel"><div className="panel-heading"><div><div className="panel-title">Extracted event</div><div className="panel-sub">Structured metadata · reviewed source</div></div><span className="status-pill indexed">INDEXED</span></div><div className="confidence-block"><div><span>EXTRACTION CONFIDENCE</span><b>{Math.round(event.confidence*100)}%</b></div><div className="confidence-bar"><i style={{width:`${Math.round(event.confidence*100)}%`}}/></div><small>Confidence reflects extraction quality, not event prediction or operational certainty.</small></div><div className="extraction-fields"><div><span>WELL</span><b>{well.name}</b></div><div><span>EVENT TYPE</span><b><span className="event-type-chip"><i/>{event.type}</span></b></div><div><span>DEPTH INTERVAL</span><b>{fmt(event.from)}–{fmt(event.to)} m</b></div><div><span>FORMATION</span><b>{well.formation}</b></div><div><span>EVENT DATE</span><b>{event.date}</b></div><div><span>SEVERITY</span><b><span className="severity-pill high">{event.severity.toUpperCase()}</span></b></div><div className="full"><span>SOURCE PASSAGE</span><blockquote>“{event.summary}”</blockquote></div><div><span>REVIEW STATUS</span><b>Human verification pending</b></div></div><div className="related-evidence"><b>RELATED COMPARABLE WELL</b><button onClick={()=>go('Offset wells')}><MapPin size={14}/>{wells[5].name}<span>82 match</span><ArrowRight size={13}/></button></div><div className="evidence-actions"><Button icon={ExternalLink} onClick={()=>notify('Full synthetic report preview opened')}>Open full report</Button><Button icon={Plus} onClick={()=>notify('Event added to comparison set')}>Compare</Button><Button kind={flagged?'primary':'quiet'} icon={flagged?Check:AlertTriangle} onClick={()=>{setFlagged(!flagged);notify(flagged?'Flag removed':'Extraction flagged for review')}}>{flagged?'Flagged':'Flag extraction'}</Button></div></aside></div></>}

function Monitoring({active,depth,setDepth,playing,setPlaying,speed,setSpeed,alerts,go,onEvidence}:{active:Well;depth:number;setDepth:(n:number)=>void;playing:boolean;setPlaying:(b:boolean)=>void;speed:number;setSpeed:(n:number)=>void;alerts:Alert[];go:(p:Page)=>void;onEvidence:(w:Well)=>void}){const points=telemetry.map((p,i)=>({...p,depth:i<telemetry.length-1?Math.min(p.depth,depth-(telemetry.length-1-i)*13):depth}));const newest=alerts[0];return <><PageHeading eyebrow="OPERATIONS · ACTIVE WELL MONITORING" title="Live well monitoring" sub="Replay synthetic telemetry alongside historical event intervals." actions={<span className="replay-label"><span className="pulse"/> REPLAY MODE · SYNTHETIC TELEMETRY</span>}/><div className="monitor-top"><div className="monitor-well"><div className="well-icon-big"><Radio size={18}/></div><div><small>ACTIVE WELL</small><b>{active.name} <span className="status-pill active">DRILLING</span></b><span>{active.formation} · Upper Assam Basin · Synthetic</span></div><ChevronDown size={16}/></div><div className="depth-readout"><small>MEASURED DEPTH</small><b>{fmt(depth)} <i>m</i></b><span><span className="health-dot"/> Receiving telemetry</span></div><div className="replay-controls"><button className={`play-control ${playing?'playing':''}`} onClick={()=>setPlaying(!playing)}>{playing?<Pause size={16}/>:<Play size={16}/>} {playing?'Pause replay':'Start replay'}</button><button className="reset-control" onClick={()=>{setPlaying(false);setDepth(1780)}} aria-label="Reset replay"><RefreshCw size={15}/></button><label>Speed <select value={speed} onChange={e=>setSpeed(+e.target.value)}><option value={1}>1×</option><option value={2}>2×</option><option value={4}>4×</option></select></label></div></div><div className="telemetry-grid"><section className="panel telemetry-chart-panel"><div className="panel-heading"><div><div className="panel-title">Measured depth &amp; rate of penetration</div><div className="panel-sub">WITSML-shaped synthetic replay · last 6 hours</div></div><span className="chart-live"><i/> {playing?'REPLAYING':'PAUSED'}</span></div><div className="chart-wrap large-chart"><ResponsiveContainer width="100%" height="100%"><AreaChart data={points}><defs><linearGradient id="cyanFill" x1="0" y1="0" x2="0" y2="1"><stop offset="5%" stopColor="#00b8d9" stopOpacity={.2}/><stop offset="95%" stopColor="#00b8d9" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="time" tick={{fontSize:10}}/><YAxis yAxisId="a" tick={{fontSize:10}}/><YAxis yAxisId="b" orientation="right" tick={{fontSize:10}}/><ChartTooltip/><Area yAxisId="a" dataKey="depth" stroke="#00a4c7" strokeWidth={2} fill="url(#cyanFill)"/><Line yAxisId="b" dataKey="rop" name="ROP" stroke="#e89a26" dot={false} strokeWidth={2}/></AreaChart></ResponsiveContainer></div><div className="chart-legend"><span><i className="dot-cyan"/> Measured depth (m)</span><span><i className="dot-amber"/> Rate of penetration (m/hr)</span></div></section><section className="panel gauge-panel"><div className="panel-heading"><div><div className="panel-title">Drilling parameters</div><div className="panel-sub">Most recent replayed values</div></div><span className="synthetic-tag"><span/> SIMULATED</span></div>{[{n:'Weight on bit',v:'18.4',u:'klb',t:'weight'},{n:'Rotary torque',v:'14.2',u:'kft·lbf',t:'torque'},{n:'Standpipe pressure',v:'2,318',u:'psi',t:'pressure'}].map((p,i)=><div className="parameter-row" key={p.n}><div className="parameter-top"><span>{p.n}</span><b>{p.v} <i>{p.u}</i></b></div><div className="parameter-spark"><ResponsiveContainer width="100%" height="100%"><LineChart data={telemetry}><Line dataKey={p.t} stroke={['#00a4c7','#727ce2','#13ad9b'][i]} dot={false} strokeWidth={1.7}/></LineChart></ResponsiveContainer></div></div>)}</section></div><div className="monitor-bottom"><section className="panel risk-panel"><div className="panel-heading"><div><div className="panel-title">Upcoming historical risk intervals</div><div className="panel-sub">Comparable event depths · cited source pages</div></div><button className="text-link" onClick={()=>go('Offset wells')}>Compare offsets <ArrowRight size={13}/></button></div><div className="risk-chart"><div className="risk-axis"><span>1,900 m</span><span>2,000 m</span><span>2,100 m</span><span>2,200 m</span></div><div className="risk-track"><div className="risk-range" style={{left:'25%',width:'20%'}}><span>LOST CIRCULATION</span></div><div className="risk-range range-two" style={{left:'31%',width:'18%'}}/><div className="depth-cursor" style={{left:`${Math.max(3,Math.min(97,(depth-1900)/3))}%`}}><i/><b>{fmt(depth)} m</b></div></div><div className="risk-well-rows"><span>{wells[2].name}</span><span className="risk-rowbar"/><span>2,000–2,080 m · RPT-003 p.4</span><span>{wells[5].name}</span><span className="risk-rowbar second"/><span>2,025–2,090 m · RPT-006 p.6</span></div></div><div className="risk-note"><AlertTriangle size={14}/><span>Historical intervals indicate recorded events in comparable synthetic wells. They do not predict an event on the active well.</span></div></section><section className="panel stream-panel"><div className="panel-heading"><div><div className="panel-title">Event stream</div><div className="panel-sub">Telemetry and evidence alerts</div></div><span className="live-badge"><i/> LIVE</span></div><div className="stream-row"><span className="stream-dot blue"/><div><b>Telemetry update received</b><small>{fmt(depth)} m · {active.formation}</small></div><time>now</time></div>{newest&&<div className="stream-row"><span className="stream-dot amber"/><div><b>Historical interval alert</b><small>{newest.type} · 2 supporting offset reports</small></div><button onClick={()=>go('Alerts')}>Review</button></div>}<div className="stream-row"><span className="stream-dot teal"/><div><b>Report index healthy</b><small>24 reports available for retrieval</small></div><time>09:31</time></div></section></div></>}

function AlertsPage({alerts,action,audit,note,setNote,onEvidence}:{alerts:Alert[];action:(a:Alert,s:'Acknowledged'|'Dismissed'|'Under investigation')=>void;audit:any[];note:string;setNote:(s:string)=>void;onEvidence:()=>void}){const [chosen,setChosen]=useState(alerts[0]);return <><PageHeading eyebrow="SAFETY CONTEXT · HISTORICAL EVIDENCE" title="Alert center" sub="Review evidence-linked intervals and record human disposition." actions={<span className="replay-label"><ShieldCheck size={14}/> HUMAN REVIEW REQUIRED</span>}/><div className="alerts-layout"><section className="panel alert-list-panel"><div className="panel-heading"><div><div className="panel-title">Alert queue <span className="count-pill">{alerts.filter(a=>a.status==='New').length} new</span></div><div className="panel-sub">Historical comparisons · latest first</div></div><select className="filter-select"><option>All statuses</option><option>New</option><option>Acknowledged</option><option>Dismissed</option></select></div>{alerts.map(a=><button key={a.id} className={`alert-queue-row ${chosen?.id===a.id?'selected':''}`} onClick={()=>setChosen(a)}><span className={`alert-queue-icon ${a.severity.toLowerCase()}`}><AlertTriangle size={16}/></span><span className="alert-queue-copy"><b>{a.type} interval ahead</b><small>{a.wellId} · {fmt(a.current)} m · {a.created}</small></span><span className={`status-pill ${a.status==='New'?'new':a.status==='Acknowledged'?'ack':'dismiss'}`}>{a.status.toUpperCase()}</span></button>)}{alerts.length===0&&<Empty icon={CheckCircle2} title="No alerts" sub="Evidence-backed alerts will appear here during replay."/>}</section><section className="panel alert-detail-panel">{chosen?<><div className="alert-detail-heading"><span className="severity-pill high"><i/> {chosen.severity.toUpperCase()} PRIORITY</span><span className={`status-pill ${chosen.status==='New'?'new':'ack'}`}>{chosen.status.toUpperCase()}</span></div><h2>{chosen.type} interval ahead</h2><p className="alert-detail-sub">Historical interval match · generated {chosen.created}</p><div className="alert-current-depth"><span>ACTIVE WELL · {chosen.wellId}</span><b>{fmt(chosen.current)} <i>m current depth</i></b><div className="alert-track-big"><div style={{left:`${Math.min(82,Math.max(10,(chosen.current-chosen.from)/(chosen.to-chosen.from)*60+10))}%`}}><i/><span>CURRENT</span></div><b>{fmt(chosen.from)}–{fmt(chosen.to)} m</b></div></div><div className="alert-fields"><span>HISTORICAL EVENT<b>{chosen.type}</b></span><span>COMPARABLE OFFSETS<b>2 synthetic wells</b></span><span>RISK INTERVAL<b>{fmt(chosen.from)}–{fmt(chosen.to)} m</b></span><span>SIMILARITY<b>82 / 100 weighted score</b></span></div><div className="alert-evidence-box"><div><FileCheck2 size={16}/><b>Supporting historical evidence</b><span>2 source pages</span></div>{chosen.sources.map((s,i)=><button key={s} onClick={onEvidence}><FileText size={14}/>{s}-DDR.pdf · page {i===0?4:6}<ArrowRight size={13}/></button>)}</div><div className="recommendation-copy"><ShieldCheck size={16}/><span>Review the cited historical evidence and validate with the drilling team.</span></div><div className="alert-actions-row"><Button kind="primary" icon={Check} onClick={()=>action(chosen,'Acknowledged')}>Acknowledge</Button><Button icon={Eye} onClick={()=>action(chosen,'Under investigation')}>Investigate</Button><Button kind="danger" icon={X} onClick={()=>action(chosen,'Dismissed')}>Dismiss</Button></div><div className="note-control"><input placeholder="Add a review note…" value={note} onChange={e=>setNote(e.target.value)} onKeyDown={e=>e.key==='Enter'&&note.trim()&&(note.trim(),setNote(''))}/><button onClick={()=>{if(note.trim()){setNote('');}}}>Add note</button></div><div className="audit-mini"><b>ALERT HISTORY</b>{audit.slice(0,3).map((x:any,i:number)=><div key={i}><span className="timeline-point"/><span>{x.action} · {x.entity}</span><time>{x.time}</time></div>)}</div></>:<Empty icon={AlertTriangle} title="Select an alert" sub="Choose an alert from the queue to review evidence."/>}</section></div></>}

function Documents({docs,setDocs,uploading,setUploading,reviews,setPage,notify}:{docs:number;setDocs:(n:number)=>void;uploading:boolean;setUploading:(b:boolean)=>void;reviews:string[];setPage:(p:Page)=>void;notify:(s:string)=>void}){const [step,setStep]=useState(0);const start=()=>{setUploading(true);setStep(0);let s=0;const t=window.setInterval(()=>{s++;setStep(s);if(s>=7){window.clearInterval(t);setUploading(false);setDocs(docs+1);notify('Synthetic report indexed and added to review workflow')}},430)};return <><PageHeading eyebrow="KNOWLEDGE BASE · DOCUMENT INGESTION" title="Document ingestion" sub="Demonstrate report processing and human verification with synthetic files." actions={<Button icon={ClipboardList} onClick={()=>setPage('Review queue')}>Review queue <span className="count-pill">{reviews.length}</span></Button>}/><div className="ingestion-grid"><div className="ingest-main"><section className="panel upload-panel"><div className="panel-heading"><div><div className="panel-title">Upload a drilling report</div><div className="panel-sub">PDF · up to 25 MB · synthetic demonstration only</div></div><span className="synthetic-tag"><span/> NO LIVE DATA</span></div><label className="dropzone"><input type="file" accept="application/pdf" onChange={start}/><div className="upload-icon"><Upload size={21}/></div><b>Drop a PDF here or <span>browse files</span></b><small>PDF only · maximum file size 25 MB</small><button type="button" onClick={e=>{e.preventDefault();start()}} disabled={uploading}>{uploading?'Processing…':'Choose synthetic sample report'}</button></label>{uploading&&<div className="upload-progress"><div className="progress-title"><b>OIL-SYN-001-DDR-025.pdf</b><span>{Math.round(step/7*100)}%</span></div><div className="confidence-bar"><i style={{width:`${step/7*100}%`}}/></div><div className="processing-steps">{['Validation','OCR','Text extraction','Table extraction','Entity extraction','Normalization','Indexing'].map((s,i)=><span className={i<step?'done':i===step?'current':''} key={s}>{i<step?<Check size={12}/>:<i/>}{s}</span>)}</div></div>}</section><section className="panel document-table-panel"><div className="panel-heading"><div><div className="panel-title">Indexed reports</div><div className="panel-sub">{docs} documents · all synthetic</div></div><div className="table-tools"><div className="tiny-search"><Search size={14}/><input placeholder="Find document"/></div><button className="icon-btn" aria-label="Filter documents"><Filter size={15}/></button></div></div><div className="table-scroll"><table><thead><tr><th>DOCUMENT</th><th>WELL</th><th>REPORT TYPE</th><th>STATUS</th><th>CONFIDENCE</th><th></th></tr></thead><tbody>{reports.slice(0,9).map((r:any,i:number)=><tr key={r.id}><td><span className="doc-table-name"><FileText size={15}/><span><b>{r.filename}</b><small>{r.date} · {r.pages} pages</small></span></span></td><td>{r.wellId}</td><td>{r.type}</td><td><span className={`status-pill ${r.status==='Needs review'?'review':'indexed'}`}><i/>{r.status.toUpperCase()}</span></td><td><span className={r.confidence<.7?'confidence-low':'confidence-high'}>{Math.round(r.confidence*100)}%</span></td><td><button className="icon-btn" aria-label={`Open ${r.filename}`}><MoreHorizontal size={16}/></button></td></tr>)}</tbody></table></div><button className="table-load" onClick={()=>notify('Showing all synthetic documents')}>View all {docs} reports <ArrowRight size={13}/></button></section></div><aside className="panel pipeline-panel"><div className="panel-title">Extraction pipeline</div><div className="panel-sub">Document to reviewed evidence</div><div className="pipeline-list">{['File validation','OCR','Text extraction','Table extraction','Entity extraction','Event extraction','Unit normalization','Indexing'].map((s,i)=><div className="pipeline-step" key={s}><span className={i<6?'pipe-done':i===6?'pipe-current':''}>{i<6?<Check size={12}/>:i+1}</span><b>{s}</b><small>{i<6?'READY':i===6?'READY':'QUEUED'}</small></div>)}</div><div className="pipeline-note"><ShieldCheck size={15}/><span>Low-confidence extractions are sent to a human review queue before evidence is treated as approved.</span></div><div className="pipeline-stat"><span>INDEXED REPORTS</span><b>{docs}<small> / 25 demo capacity</small></b><div className="confidence-bar"><i style={{width:`${Math.min(100,docs/25*100)}%`}}/></div></div></aside></div></>}

function ReviewQueue({reviews,setReviews,log,notify,onEvidence}:{reviews:string[];setReviews:(v:string[])=>void;log:(a:string,e:string)=>void;notify:(s:string)=>void;onEvidence:()=>void}){const [selected,setSelected]=useState(0);const [edit,setEdit]=useState('Synthetic Sandstone A');const rows=reviews.length?reviews.map((id,i)=>({id,filename:id==='RPT-021'?'OIL-SYN-009-DDR-021.pdf':'OIL-SYN-001-DDR-025.pdf',page:5,field:'Formation',value:'Sandstone A / Shale B',confidence:id==='RPT-021'?62:78,suggest:'Synthetic Sandstone A'})):[];const review=(verb:string)=>{const r=rows[selected];if(!r)return;log(`Extraction ${verb.toLowerCase()}`,`${r.id} · ${r.field}`);setReviews(reviews.filter(x=>x!==r.id));setSelected(0);notify(`Extraction ${verb.toLowerCase()}`)};return <><PageHeading eyebrow="DATA QUALITY · HUMAN VERIFICATION" title="Extraction review queue" sub="Review uncertain fields against the source passage before indexing." actions={<span className="status-pill review"><i/> {reviews.length} NEEDS REVIEW</span>}/><div className="review-layout"><section className="panel review-table-panel"><div className="panel-heading"><div><div className="panel-title">Low-confidence extractions</div><div className="panel-sub">Suggested values are demo parser output, not verified operational facts.</div></div><button className="icon-btn"><Filter size={15}/></button></div>{rows.length?<div className="table-scroll"><table><thead><tr><th>DOCUMENT / PAGE</th><th>FIELD</th><th>EXTRACTED VALUE</th><th>CONFIDENCE</th><th>STATUS</th></tr></thead><tbody>{rows.map((r,i)=><tr key={r.id} onClick={()=>{setSelected(i);setEdit(r.suggest)}} className={selected===i?'selected-row':''}><td><b>{r.filename}</b><small>Page {r.page} · {r.id}</small></td><td>{r.field}</td><td>{r.value}</td><td><span className="confidence-low">{r.confidence}%</span></td><td><span className="status-pill review">NEEDS REVIEW</span></td></tr>)}</tbody></table></div>:<Empty icon={CheckCircle2} title="Review queue clear" sub="New low-confidence extractions will appear here."/>}<div className="review-bottom"><span><ShieldCheck size={14}/> Only reviewed extractions are marked approved.</span><span>Showing {rows.length} of {rows.length}</span></div></section><aside className="panel source-review-panel"><div className="panel-heading"><div><div className="panel-title">Source passage</div><div className="panel-sub">Original context for selected extraction</div></div></div>{rows[selected]?<><div className="review-source-meta"><FileText size={15}/><b>{rows[selected].filename}</b><span>PAGE {rows[selected].page}</span></div><div className="review-passage">“Formation top noted near the interval. The drilling summary references the Synthetic Sandstone A section. Please verify the formation boundary against the source log before approval.”</div><div className="review-edit"><label>FIELD VALUE · {rows[selected].field.toUpperCase()}</label><input value={edit} onChange={e=>setEdit(e.target.value)}/><div className="suggested-value"><span>SUGGESTED VALUE</span><b>{rows[selected].suggest}</b></div></div><div className="review-actions"><Button kind="primary" icon={Check} onClick={()=>review('Approved')}>Approve</Button><Button icon={Settings} onClick={()=>review('Edited')}>Save edit</Button><Button kind="danger" icon={X} onClick={()=>review('Rejected')}>Reject</Button></div><button className="citation-link" onClick={onEvidence}><Eye size={13}/> Open source page <ArrowRight size={12}/></button></>:<div className="empty-review">Select a pending extraction to review its source passage.</div>}</aside></div></>}

function Analytics(){const eventData=[{name:'Lost circulation',count:8,fill:'#e8a434'},{name:'Stuck pipe',count:6,fill:'#e06c61'},{name:'NPT',count:5,fill:'#6585c8'},{name:'Kick',count:3,fill:'#9b78c9'},{name:'Equipment',count:4,fill:'#44a899'}];const formationData=[{name:'Sandstone A',events:12},{name:'Shale B',events:8},{name:'Limestone C',events:5},{name:'Deltaic D',events:7}];return <><PageHeading eyebrow="INSIGHTS · SYNTHETIC DATA" title="Operations analytics" sub="Patterns across demo records · descriptive only, not forecasts." actions={<span className="synthetic-tag"><span/> DEMONSTRATION DATA</span>}/><div className="analytics-metrics"><Metric label="SYNTHETIC EVENTS" value="26" icon={Activity} trend="Across 12 fictional wells"/><Metric label="NPT RECORDS" value="05" icon={Clock3} trend="Descriptive sample count" accent="amber"/><Metric label="ALERT ACKNOWLEDGMENT" value="94%" icon={CheckCircle2} trend="Demo workflow only" accent="teal"/><Metric label="SEARCHES THIS SESSION" value="18" icon={Search} trend="Synthetic session activity" accent="purple"/></div><div className="analytics-grid"><section className="panel analytics-chart"><div className="panel-heading"><div><div className="panel-title">Events by type</div><div className="panel-sub">Count in synthetic indexed reports</div></div><button className="icon-btn"><MoreHorizontal size={16}/></button></div><div className="chart-wrap analytics-bars"><ResponsiveContainer width="100%" height="100%"><AreaChart data={eventData}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="name" tick={{fontSize:10}}/><YAxis tick={{fontSize:10}}/><ChartTooltip/><Area dataKey="count" stroke="#00a4c7" fill="#00b8d925" strokeWidth={2}/></AreaChart></ResponsiveContainer></div><div className="chart-legend">Data represents fictional reports created for product demonstration.</div></section><section className="panel analytics-chart"><div className="panel-heading"><div><div className="panel-title">Events by formation</div><div className="panel-sub">Synthetic records · no real-well inference</div></div></div><div className="formation-stats">{formationData.map((f,i)=><div key={f.name}><span className={`formation-color fc${i}`}/><span>{f.name}</span><div className="formation-stat-bar"><i style={{width:`${f.events/12*100}%`}}/></div><b>{f.events}</b></div>)}</div></section><section className="panel analytics-chart"><div className="panel-heading"><div><div className="panel-title">Report processing</div><div className="panel-sub">Document pipeline status</div></div><span className="status-pill indexed">HEALTHY</span></div><div className="processing-summary"><div><b>24</b><span>Indexed</span><i style={{width:'92%'}}/></div><div><b>01</b><span>Needs review</span><i style={{width:'8%',background:'#f2ad43'}}/></div><div><b>00</b><span>Failed</span><i style={{width:'0%',background:'#d96c66'}}/></div></div></section><section className="panel analytics-chart"><div className="panel-heading"><div><div className="panel-title">Alerts by disposition</div><div className="panel-sub">Prototype workflow activity</div></div></div><div className="disposition-list"><div><span className="disp-dot amber"/><span>New</span><b>{String(1).padStart(2,'0')}</b><small>Requires review</small></div><div><span className="disp-dot teal"/><span>Acknowledged</span><b>{String(12).padStart(2,'0')}</b><small>Human disposition</small></div><div><span className="disp-dot gray"/><span>Dismissed</span><b>{String(2).padStart(2,'0')}</b><small>Recorded decisions</small></div></div></section></div><div className="analytics-caveat"><ShieldCheck size={15}/><span><b>Interpretation:</b> all counts and patterns on this page use fictional demonstration data. They do not indicate real OIL performance, forecast events, or establish an operational impact.</span></div></>}

function Audit({audit}:{audit:any[]}){const [term,setTerm]=useState('');const rows=audit.filter(a=>!term||`${a.user} ${a.action} ${a.entity}`.toLowerCase().includes(term.toLowerCase()));return <><PageHeading eyebrow="GOVERNANCE · ACTIVITY HISTORY" title="Audit trail" sub="Recorded prototype actions with timestamps and actor context." actions={<Button icon={Download}>Export log</Button>}/><div className="audit-summary"><div><ShieldCheck size={17}/><span><b>Activity recording active</b><small>Append-only visual history for this demo session.</small></span><span className="health-dot"/></div><span className="synthetic-tag"><span/> DEMO SESSION</span></div><section className="panel audit-table-panel"><div className="panel-heading"><div><div className="panel-title">Recorded activity</div><div className="panel-sub">{rows.length} entries · newest first</div></div><div className="table-tools"><div className="tiny-search"><Search size={14}/><input placeholder="Search activity" value={term} onChange={e=>setTerm(e.target.value)}/></div><select className="filter-select"><option>All actions</option><option>Searches</option><option>Alert actions</option><option>Document reviews</option></select></div></div><div className="table-scroll"><table><thead><tr><th>USER / ROLE</th><th>ACTION</th><th>ENTITY</th><th>TIMESTAMP</th><th>STATUS</th></tr></thead><tbody>{rows.map((a:any,i:number)=><tr key={i}><td><span className="audit-user"><span className="avatar tiny">{a.user==='System'?'SY':a.user.split(' ').map((x:string)=>x[0]).join('')}</span><span><b>{a.user}</b><small>{a.role}</small></span></span></td><td>{a.action}</td><td>{a.entity}</td><td className="mono-time">{a.time}</td><td><span className="status-pill indexed">{a.status.toUpperCase()}</span></td></tr>)}</tbody></table></div><div className="audit-foot"><ShieldCheck size={14}/><span>Actions are recorded to provide traceability in this prototype. This visual log does not claim cryptographic immutability.</span></div></section></>}

function Empty({icon:Icon,title,sub}:{icon:any;title:string;sub:string}){return <div className="empty-state"><div><Icon size={19}/></div><b>{title}</b><span>{sub}</span></div>}
function Glossary({onClose}:{onClose:()=>void}){const terms=[['Offset well','A previously drilled well used as a historical comparison for a nearby or geologically similar well.'],['Formation','A named rock interval with shared geological characteristics.'],['NPT','Non-productive time recorded during drilling operations.'],['Kick','An influx of formation fluid into the wellbore that requires qualified operational response.'],['Lost circulation','Drilling fluid loss into the formation, as recorded in historical reports.'],['Stuck pipe','A drill string that cannot be moved as expected, recorded as a historical event.'],['WITSML','An industry data exchange standard for wellsite information; this demo uses shaped mock records.'],['OCR','Optical character recognition, used to turn scanned document images into searchable text.'],['Hybrid search','Retrieval that combines exact keyword matching with semantic similarity.'],['Evidence confidence','A signal about extraction or retrieval quality; it is not operational certainty or event probability.']];return <div className="modal-shade" onClick={onClose}><div className="glossary-modal" onClick={e=>e.stopPropagation()}><div className="modal-heading"><div><span className="eyebrow">REFERENCE · DOMAIN TERMS</span><h2>Field glossary</h2></div><button className="icon-btn" onClick={onClose} aria-label="Close glossary"><X size={18}/></button></div><div className="glossary-list">{terms.map(([t,d])=><div key={t}><b>{t}</b><span>{d}</span></div>)}</div><div className="glossary-note"><ShieldAlert size={14}/>This glossary is for prototype orientation and does not replace field procedures or expert review.</div></div></div>}


